const safeRows = (nodeName, keyField) => {
  try {
    return $(nodeName).all().map((i) => i.json).filter((r) => r && r[keyField]);
  } catch {
    return [];
  }
};

let isHtml = false;
try {
  isHtml = $('Webhook — Serve Admin Portal').all().length > 0;
} catch {
  isHtml = false;
}

const leads = safeRows('Read All Leads', 'lead_key').sort((a, b) => String(b.updated_at || '').localeCompare(String(a.updated_at || '')));
const customers = safeRows('Read All Customers', 'customer_key').sort((a, b) => Number(b.risk_score || 0) - Number(a.risk_score || 0));
const tickets = safeRows('Read All Tickets', 'ticket_code').sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')));
const activities = safeRows('Read Activity Log', 'event_code').sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || ''))).slice(0, 40);

const activeCustomers = customers.filter((c) => String(c.account_status || 'Active').toLowerCase() === 'active');
const totalMrr = activeCustomers.reduce((s, c) => s + Number(c.mrr_usd || 0), 0);
const atRisk = activeCustomers.filter((c) => ['AT_RISK', 'URGENT'].includes(String(c.current_risk_level || '').toUpperCase()));
const atRiskMrr = atRisk.reduce((s, c) => s + Number(c.mrr_usd || 0), 0);
const convertedLeads = leads.filter((l) => Boolean(l.converted_at) || /converted/i.test(String(l.pipeline_status || ''))).length;
const conversionRate = leads.length > 0 ? Math.round((convertedLeads / leads.length) * 100) : 0;
const openTickets = tickets.filter((t) => !/closed|replied|resolved/i.test(String(t.ticket_status || '')));
const criticalTickets = openTickets.filter((t) => ['HIGH', 'CRITICAL'].includes(String(t.urgency || '').toUpperCase()));

const snapshot = {
  ok: true,
  generated_at: new Date().toISOString(),
  sheet_url: 'https://docs.google.com/spreadsheets/d/CONFIGURE_GOOGLE_SHEET_ID',
  kpis: {
    total_mrr: totalMrr,
    at_risk_mrr: atRiskMrr,
    at_risk_count: atRisk.length,
    total_customers: activeCustomers.length,
    total_leads: leads.length,
    converted_leads: convertedLeads,
    conversion_rate: conversionRate,
    open_tickets: openTickets.length,
    critical_tickets: criticalTickets.length,
    total_events: activities.length,
  },
  leads,
  customers,
  tickets,
  activities,
};

if (!isHtml) {
  return [{ json: { is_html: false, overview: snapshot } }];
}

const safeSeed = JSON.stringify(snapshot)
  .replace(/</g, '\\u003c')
  .replace(/>/g, '\\u003e')
  .replace(/\u2028/g, '\\u2028')
  .replace(/\u2029/g, '\\u2029');

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>SaaS CRM SaaS CRM — Command Portal</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <script defer src="https://cdn.jsdelivr.net/npm/alpinejs@3.x.x/dist/cdn.min.js"></script>
</head>
<body class="bg-slate-950 text-slate-100 min-h-screen antialiased" x-data="crmPortal()">
  <script id="crm-seed" type="application/json">${safeSeed}</script>
  <header class="border-b border-slate-800 bg-slate-900/80 backdrop-blur sticky top-0 z-20">
    <div class="max-w-7xl mx-auto px-6 py-4 flex flex-wrap items-center justify-between gap-4">
      <div class="flex items-center gap-3">
        <div class="w-9 h-9 rounded-lg bg-indigo-600 flex items-center justify-center font-bold text-white">AI</div>
        <div>
          <h1 class="text-lg font-semibold tracking-tight">SaaS CRM SaaS CRM Command Portal</h1>
          <p class="text-xs text-slate-400">n8n Orchestrated Revenue, Churn &amp; Support Operations</p>
        </div>
      </div>
      <div class="flex items-center gap-2.5">
        <a :href="data.sheet_url" target="_blank" class="px-3 py-1.5 rounded-lg bg-emerald-600/20 text-emerald-300 border border-emerald-500/30 text-xs font-medium hover:bg-emerald-600/30">Google Sheets Mirror</a>
        <button @click="authModal = true" class="px-3 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 border border-slate-700 text-xs font-medium" x-text="apiSecret ? 'Operator Auth Connected' : 'Connect Operator Auth'"></button>
        <button @click="refreshOverview()" :disabled="loading" class="px-3 py-1.5 rounded-lg bg-indigo-600 hover:bg-indigo-500 text-xs font-medium disabled:opacity-50" x-text="loading ? 'Syncing...' : 'Refresh Data'"></button>
      </div>
    </div>
  </header>

  <main class="max-w-7xl mx-auto px-6 py-6 space-y-6">
    <template x-if="toast">
      <div class="rounded-lg px-4 py-3 text-sm border" :class="toastError ? 'bg-rose-950/60 border-rose-700 text-rose-200' : 'bg-emerald-950/60 border-emerald-700 text-emerald-200'" x-text="toast"></div>
    </template>

    <section class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
      <div class="rounded-xl bg-slate-900 border border-slate-800 p-4">
        <p class="text-xs uppercase tracking-wider text-slate-400">Active SaaS MRR</p>
        <p class="text-2xl font-bold text-emerald-400 mt-1" x-text="'$' + (data.kpis.total_mrr || 0).toLocaleString()"></p>
        <p class="text-xs text-slate-400 mt-1" x-text="(data.kpis.total_customers || 0) + ' Active Subscriptions'"></p>
      </div>
      <div class="rounded-xl bg-slate-900 border border-slate-800 p-4">
        <p class="text-xs uppercase tracking-wider text-slate-400">Churn Exposure</p>
        <p class="text-2xl font-bold text-rose-400 mt-1" x-text="'$' + (data.kpis.at_risk_mrr || 0).toLocaleString()"></p>
        <p class="text-xs text-slate-400 mt-1" x-text="(data.kpis.at_risk_count || 0) + ' At-Risk / Urgent Accounts'"></p>
      </div>
      <div class="rounded-xl bg-slate-900 border border-slate-800 p-4">
        <p class="text-xs uppercase tracking-wider text-slate-400">Lead Pipeline</p>
        <p class="text-2xl font-bold text-sky-400 mt-1" x-text="data.kpis.total_leads || 0"></p>
        <p class="text-xs text-slate-400 mt-1" x-text="(data.kpis.conversion_rate || 0) + '% Converted (' + (data.kpis.converted_leads || 0) + ')'"></p>
      </div>
      <div class="rounded-xl bg-slate-900 border border-slate-800 p-4">
        <p class="text-xs uppercase tracking-wider text-slate-400">Open Support Tickets</p>
        <p class="text-2xl font-bold text-amber-400 mt-1" x-text="data.kpis.open_tickets || 0"></p>
        <p class="text-xs text-slate-400 mt-1" x-text="(data.kpis.critical_tickets || 0) + ' High / Critical Priority'"></p>
      </div>
    </section>

    <div class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-800 pb-3">
      <div class="flex gap-2">
        <template x-for="t in ['overview','leads','customers','tickets','activity']" :key="t">
          <button @click="tab = t" class="px-3.5 py-1.5 rounded-lg text-sm font-medium capitalize transition" :class="tab === t ? 'bg-indigo-600 text-white' : 'bg-slate-900 text-slate-300 hover:bg-slate-800'" x-text="t"></button>
        </template>
      </div>
      <input x-model="search" type="search" placeholder="Filter by name, company, email, code..." class="bg-slate-900 border border-slate-700 rounded-lg px-3 py-1.5 text-sm w-64 focus:outline-none focus:border-indigo-500" />
    </div>

    <section x-show="tab === 'overview'" class="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <div class="rounded-xl bg-slate-900 border border-slate-800 p-5">
        <h2 class="text-sm font-semibold text-slate-200 mb-3">Customer Churn Watchlist</h2>
        <div class="space-y-2.5 max-h-96 overflow-y-auto">
          <template x-for="c in filteredCustomers()" :key="c.customer_key">
            <div class="p-3 rounded-lg bg-slate-950 border border-slate-800 flex items-start justify-between gap-3">
              <div>
                <p class="font-medium text-sm" x-text="c.name + ' · ' + c.company"></p>
                <p class="text-xs text-slate-400" x-text="c.subscription_plan + ' ($' + c.mrr_usd + '/mo) · ' + c.last_active_days + 'd inactive · ' + c.open_tickets_count + ' open tickets'"></p>
                <p class="text-xs text-slate-300 mt-1" x-text="c.recommended_action"></p>
              </div>
              <span class="px-2 py-0.5 rounded text-xs font-semibold shrink-0" :class="riskBadge(c.current_risk_level)" x-text="c.current_risk_level + ' (' + c.risk_score + ')'"></span>
            </div>
          </template>
          <p x-show="filteredCustomers().length === 0" class="text-xs text-slate-500">No customers seeded yet.</p>
        </div>
      </div>

      <div class="rounded-xl bg-slate-900 border border-slate-800 p-5">
        <h2 class="text-sm font-semibold text-slate-200 mb-3">Recent System Activity Timeline</h2>
        <div class="space-y-2.5 max-h-96 overflow-y-auto">
          <template x-for="a in data.activities.slice(0, 15)" :key="a.event_code">
            <div class="p-3 rounded-lg bg-slate-950 border border-slate-800">
              <div class="flex items-center justify-between text-xs text-slate-400">
                <span class="font-mono text-indigo-400" x-text="a.event_type"></span>
                <span x-text="(a.created_at || '').slice(0, 19).replace('T', ' ')"></span>
              </div>
              <p class="text-sm text-slate-200 mt-1" x-text="a.summary"></p>
            </div>
          </template>
          <p x-show="data.activities.length === 0" class="text-xs text-slate-500">No activity recorded yet.</p>
        </div>
      </div>
    </section>

    <section x-show="tab === 'leads'" class="rounded-xl bg-slate-900 border border-slate-800 overflow-x-auto">
      <table class="w-full text-left text-sm">
        <thead class="bg-slate-950 text-slate-400 text-xs uppercase">
          <tr><th class="p-3">Lead</th><th class="p-3">Score</th><th class="p-3">Classification</th><th class="p-3">Status</th><th class="p-3">Touches</th><th class="p-3">Action</th></tr>
        </thead>
        <tbody class="divide-y divide-slate-800">
          <template x-for="l in filteredLeads()" :key="l.lead_key">
            <tr class="hover:bg-slate-800/40">
              <td class="p-3"><div class="font-medium" x-text="l.name + ' (' + l.company + ')'"></div><div class="text-xs text-slate-400" x-text="l.email"></div></td>
              <td class="p-3 font-semibold" x-text="l.lead_score + '/100'"></td>
              <td class="p-3" x-text="l.classification"></td>
              <td class="p-3 text-xs" x-text="l.pipeline_status"></td>
              <td class="p-3" x-text="l.followup_count"></td>
              <td class="p-3">
                <button x-show="!/converted/i.test(l.pipeline_status || '')" @click="convertLead(l)" class="px-2.5 py-1 rounded bg-emerald-600 hover:bg-emerald-500 text-xs font-medium">Convert to Customer</button>
                <span x-show="/converted/i.test(l.pipeline_status || '')" class="text-xs text-emerald-400 font-medium">Converted</span>
              </td>
            </tr>
          </template>
        </tbody>
      </table>
    </section>

    <section x-show="tab === 'customers'" class="rounded-xl bg-slate-900 border border-slate-800 overflow-x-auto">
      <table class="w-full text-left text-sm">
        <thead class="bg-slate-950 text-slate-400 text-xs uppercase">
          <tr><th class="p-3">Customer</th><th class="p-3">Plan / MRR</th><th class="p-3">Risk</th><th class="p-3">Inactive</th><th class="p-3">Open Tickets</th><th class="p-3">Recommendation</th></tr>
        </thead>
        <tbody class="divide-y divide-slate-800">
          <template x-for="c in filteredCustomers()" :key="c.customer_key">
            <tr class="hover:bg-slate-800/40">
              <td class="p-3"><div class="font-medium" x-text="c.name + ' (' + c.company + ')'"></div><div class="text-xs text-slate-400" x-text="c.customer_code + ' · ' + c.email"></div></td>
              <td class="p-3" x-text="c.subscription_plan + ' · $' + c.mrr_usd + '/mo'"></td>
              <td class="p-3"><span class="px-2 py-0.5 rounded text-xs font-semibold" :class="riskBadge(c.current_risk_level)" x-text="c.current_risk_level + ' (' + c.risk_score + ')'"></span></td>
              <td class="p-3" x-text="c.last_active_days + 'd'"></td>
              <td class="p-3" x-text="c.open_tickets_count"></td>
              <td class="p-3 text-xs text-slate-300" x-text="c.recommended_action"></td>
            </tr>
          </template>
        </tbody>
      </table>
    </section>

    <section x-show="tab === 'tickets'" class="rounded-xl bg-slate-900 border border-slate-800 overflow-x-auto">
      <table class="w-full text-left text-sm">
        <thead class="bg-slate-950 text-slate-400 text-xs uppercase">
          <tr><th class="p-3">Ticket</th><th class="p-3">Customer</th><th class="p-3">Intent</th><th class="p-3">Urgency</th><th class="p-3">Status</th><th class="p-3">Action</th></tr>
        </thead>
        <tbody class="divide-y divide-slate-800">
          <template x-for="t in filteredTickets()" :key="t.ticket_code">
            <tr class="hover:bg-slate-800/40">
              <td class="p-3"><div class="font-medium" x-text="t.ticket_code + ' · ' + t.subject"></div><div class="text-xs text-slate-400" x-text="t.ai_summary"></div></td>
              <td class="p-3"><div x-text="t.customer_name"></div><div class="text-xs text-slate-400" x-text="t.customer_email + ' (' + t.subscription_plan + ')'"></div></td>
              <td class="p-3 text-xs" x-text="t.intent"></td>
              <td class="p-3"><span class="px-2 py-0.5 rounded text-xs font-semibold" :class="urgencyBadge(t.urgency)" x-text="t.urgency"></span></td>
              <td class="p-3 text-xs" x-text="t.ticket_status"></td>
              <td class="p-3">
                <button x-show="!/closed/i.test(t.ticket_status || '')" @click="closeTicket(t)" class="px-2.5 py-1 rounded bg-sky-600 hover:bg-sky-500 text-xs font-medium">Resolve Ticket</button>
                <span x-show="/closed/i.test(t.ticket_status || '')" class="text-xs text-slate-400">Closed</span>
              </td>
            </tr>
          </template>
        </tbody>
      </table>
    </section>

    <section x-show="tab === 'activity'" class="rounded-xl bg-slate-900 border border-slate-800 p-5 space-y-2">
      <template x-for="a in data.activities" :key="a.event_code">
        <div class="p-3 rounded-lg bg-slate-950 border border-slate-800 flex items-center justify-between gap-4">
          <div>
            <span class="text-xs font-mono text-indigo-400 mr-2" x-text="a.event_code"></span>
            <span class="text-xs px-2 py-0.5 rounded bg-slate-800 text-slate-300" x-text="a.event_type"></span>
            <p class="text-sm mt-1" x-text="a.summary"></p>
          </div>
          <span class="text-xs text-slate-500 shrink-0" x-text="a.actor"></span>
        </div>
      </template>
    </section>
  </main>

  <div x-show="authModal" class="fixed inset-0 bg-black/70 flex items-center justify-center p-4 z-30" style="display:none">
    <div class="bg-slate-900 border border-slate-700 rounded-xl max-w-md w-full p-5 space-y-4">
      <h3 class="text-base font-semibold">Operator Header Authentication</h3>
      <p class="text-xs text-slate-400">Stored in browser sessionStorage only. Required for live JSON refresh and mutation endpoints.</p>
      <div>
        <label class="text-xs text-slate-300 block mb-1">Header Name</label>
        <input x-model="headerName" type="text" placeholder="Authorization" class="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-sm" />
      </div>
      <div>
        <label class="text-xs text-slate-300 block mb-1">Header Value / Secret</label>
        <input x-model="apiSecret" type="password" placeholder="Enter n8n Header Auth token" class="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-sm" />
      </div>
      <div class="flex justify-end gap-2">
        <button @click="authModal = false" class="px-3 py-1.5 rounded-lg bg-slate-800 text-xs">Cancel</button>
        <button @click="saveAuth()" class="px-3 py-1.5 rounded-lg bg-indigo-600 text-xs font-medium">Save Session Auth</button>
      </div>
    </div>
  </div>

  <script>
    function crmPortal() {
      const seed = JSON.parse(document.getElementById('crm-seed').textContent || '{}');
      return {
        data: seed,
        tab: 'overview',
        search: '',
        loading: false,
        authModal: false,
        headerName: sessionStorage.getItem('crm_header_name') || 'Authorization',
        apiSecret: sessionStorage.getItem('crm_api_secret') || '',
        toast: '',
        toastError: false,
        showToast(msg, isErr = false) {
          this.toast = msg;
          this.toastError = isErr;
          setTimeout(() => { this.toast = ''; }, 5000);
        },
        saveAuth() {
          sessionStorage.setItem('crm_header_name', this.headerName);
          sessionStorage.setItem('crm_api_secret', this.apiSecret);
          this.authModal = false;
          this.showToast('Session operator credentials updated.');
        },
        authHeaders() {
          if (!this.apiSecret) {
            this.authModal = true;
            throw new Error('Operator auth header required.');
          }
          const h = { 'Content-Type': 'application/json' };
          h[this.headerName] = this.apiSecret;
          return h;
        },
        async refreshOverview() {
          this.loading = true;
          try {
            const res = await fetch('/webhook/crm/api/overview', { headers: this.authHeaders() });
            if (!res.ok) throw new Error('HTTP ' + res.status);
            this.data = await res.json();
            this.showToast('Synchronized live CRM snapshot.');
          } catch (e) {
            this.showToast('Sync requires valid Operator Header Auth (' + e.message + ').', true);
          } finally {
            this.loading = false;
          }
        },
        async convertLead(lead) {
          try {
            const headers = this.authHeaders();
            const res = await fetch('/webhook/crm/api/leads/convert', {
              method: 'POST',
              headers,
              body: JSON.stringify({ lead_key: lead.lead_key, subscription_plan: 'Growth', mrr_usd: 299 }),
            });
            const out = await res.json();
            if (!res.ok) throw new Error(out.error || ('HTTP ' + res.status));
            this.showToast('Converted ' + lead.name + ' to Customer (' + out.customer_code + ').');
            await this.refreshOverview();
          } catch (e) {
            this.showToast('Convert failed: ' + e.message, true);
          }
        },
        async closeTicket(tkt) {
          try {
            const headers = this.authHeaders();
            const res = await fetch('/webhook/crm/api/tickets/close', {
              method: 'POST',
              headers,
              body: JSON.stringify({ ticket_code: tkt.ticket_code }),
            });
            const out = await res.json();
            if (!res.ok) throw new Error(out.error || ('HTTP ' + res.status));
            this.showToast('Closed ticket ' + tkt.ticket_code + '.');
            await this.refreshOverview();
          } catch (e) {
            this.showToast('Resolve failed: ' + e.message, true);
          }
        },
        matches(obj) {
          const q = (this.search || '').toLowerCase().trim();
          if (!q) return true;
          return JSON.stringify(obj).toLowerCase().includes(q);
        },
        filteredLeads() { return (this.data.leads || []).filter((x) => this.matches(x)); },
        filteredCustomers() { return (this.data.customers || []).filter((x) => this.matches(x)); },
        filteredTickets() { return (this.data.tickets || []).filter((x) => this.matches(x)); },
        riskBadge(lvl) {
          if (lvl === 'URGENT') return 'bg-rose-500/20 text-rose-300 border border-rose-500/40';
          if (lvl === 'AT_RISK') return 'bg-amber-500/20 text-amber-300 border border-amber-500/40';
          return 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/40';
        },
        urgencyBadge(u) {
          if (u === 'CRITICAL' || u === 'HIGH') return 'bg-rose-500/20 text-rose-300 border border-rose-500/40';
          if (u === 'MEDIUM') return 'bg-amber-500/20 text-amber-300 border border-amber-500/40';
          return 'bg-sky-500/20 text-sky-300 border border-sky-500/40';
        }
      };
    }
  </script>
</body>
</html>`;

return [{ json: { is_html: true, html, overview: snapshot } }];

const raw = $input.item.json || {};
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const leadKey = String(body.lead_key || body.email || '').trim().toLowerCase();
const rawPlan = String(body.subscription_plan || 'Growth').trim();
const mrrMap = { Starter: 99, Growth: 299, Scale: 699, Enterprise: 1499 };
const mrrRaw = Number(body.mrr_usd);
const mrrUsd = (!Number.isNaN(mrrRaw) && mrrRaw > 0) ? Math.round(mrrRaw) : (mrrMap[rawPlan] || 299);
return { json: { lead_key: leadKey, subscription_plan: rawPlan, mrr_usd: mrrUsd } };

const req = $('Parse Convert Request').item.json;
const lead = $input.item.json;
const nowIso = new Date().toISOString();
const email = String(lead.email || lead.lead_key).trim().toLowerCase();
let hash = 0;
for (let i = 0; i < email.length; i++) { hash = ((hash << 5) - hash) + email.charCodeAt(i); hash |= 0; }
const customerCode = 'CUST-' + Math.abs(hash).toString(16).toUpperCase().padStart(6, '0').slice(0, 6);
return {
  json: {
    lead_key: lead.lead_key,
    customer_key: email,
    customer_code: customerCode,
    name: lead.name || email.split('@')[0],
    email,
    company: lead.company || 'Direct Account',
    subscription_plan: req.subscription_plan,
    mrr_usd: req.mrr_usd,
    account_status: 'Active',
    last_active_days: 0,
    open_tickets_count: 0,
    total_tickets_count: 0,
    current_risk_level: 'HEALTHY',
    engagement_trend: 'NEW_ONBOARDING',
    risk_score: 5,
    last_reason: 'Converted via CRM Admin Command Portal.',
    recommended_action: 'Confirm onboarding kickoff call.',
    now_iso: nowIso,
    event_code: 'CONV-' + Date.now().toString(36).toUpperCase(),
  },
};

const raw = $input.item.json || {};
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
return { json: { ticket_code: String(body.ticket_code || '').trim().toUpperCase(), now_iso: new Date().toISOString() } };

const req = $('Parse Close Ticket Request').item.json;
const tkt = $('Lookup Ticket to Close').item.json;
const cust = $input.item.json || {};
const hasCust = Boolean(cust.customer_key || cust.id);
const nextOpen = hasCust ? Math.max(0, Number(cust.open_tickets_count || 0) - 1) : 0;
return {
  json: {
    has_customer: hasCust,
    ticket_code: req.ticket_code,
    customer_key: tkt.customer_key || '',
    next_open_tickets: nextOpen,
